using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Collections.Generic;using System.ComponentModel;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class QsWindows {
 static int count;static Exception uiError;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static object Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);
 static object Field(object o,string n)=>o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);
 static IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(var x in All(child))yield return x;}
 static void Pump(){Application.DoEvents();if(uiError!=null)throw uiError;}
 static void Wait(Func<bool> ready){var w=System.Diagnostics.Stopwatch.StartNew();do{Pump();if(ready())return;System.Threading.Thread.Sleep(10);}while(w.ElapsedMilliseconds<7000);throw new Exception("Zeitlimit");}
 [STAThread]static int Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.ThreadException+=(s,e)=>uiError=e.Exception;string root=Path.Combine(Path.GetTempPath(),"Musikbox-QS-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
 using(var cover=new CoverSearchView("Lainey Wilson","4x4xU",false)){
 cover.Show();Pump();foreach(var c in All(cover).Where(c=>c.Visible&&(c is Button||c is TextBoxBase||c is ComboBox||c is ListBox))){var color=c.BackColor;if(c is StudioActionButton){using(var image=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(image,c.ClientRectangle);color=image.GetPixel(c.Width/2,c.Height-4);}}Check(color.A==0||!(color.R>220&&color.G>220&&color.B>220),"Coversuche dunkles Bedienelement "+c.GetType().Name);}
 Check(cover.Find is StudioActionButton&&cover.Mode is StudioComboBox&&cover.Results is StudioListBox,"Coversuche verwendet Studio-Steuerelemente");
 var combo=cover.Mode;for(int n=0;n<4;n++){combo.DroppedDown=true;Pump();Check(combo.DroppedDown,"Eigene Dropdownliste geöffnet "+n);combo.DroppedDown=false;Pump();Check(!combo.DroppedDown,"Eigene Dropdownliste geschlossen "+n);}cover.Close();}
 using(var format=new OutputFormatView("%artist% - %title%")){format.Show();Pump();var tokens=All(format).OfType<CheckedListBox>().Single();tokens.SetItemChecked(0,false);Check(format.Pattern=="%title%","Feldabwahl sofort vor Speichern wirksam");tokens.SetItemChecked(0,true);tokens.SelectedIndex=1;All(format).OfType<Button>().Single(b=>b.Text=="Nach oben").PerformClick();Check(format.Pattern=="%title% - %artist%","Feldreihenfolge folgt Verschiebung");Check(tokens is StudioCheckedListBox,"Feldauswahl mit eigener Scrollanbindung");format.Close();}
 var device=new PlaybackTestDevice();using(var v=new MainView(Path.Combine(root,"layout.json"))){var c=new Controller(v,Path.Combine(root,"backups"),new Playback(device));var project=new Project();for(int f=0;f<3;f++){var folder=new BoxFolder{Name=f.ToString("D3")+" Test",Theme="Album",SourceDirectory=root};for(int i=0;i<8;i++){var path=Path.Combine(root,f+"-"+i+".mp3");File.WriteAllBytes(path,new byte[256]);folder.Songs.Add(new Song{Source=path,Artist="AC/DC",Title="Song "+i,Album="Album",Year="2026",Bitrate=128,TagType="ID3v2.3"});}project.Folders.Add(folder);}Call(c,"ReplaceProject",project,null,true);v.Show();v.WindowState=FormWindowState.Normal;v.ClientSize=new Size(1600,950);Pump();
 v.Songs.Sort(v.Songs.Columns["Titel"],ListSortDirection.Descending);Call(c,"SwitchLibraryMode","Ordner");v.Groups.Sort(v.Groups.Columns["Anzahl"],ListSortDirection.Ascending);Call(c,"SwitchLibraryMode","Titel");Check(v.Songs.SortedColumn.Name=="Titel"&&v.Songs.SortOrder==SortOrder.Descending,"Titelsortierung nach Ordnerwechsel erhalten");
 Call(c,"SwitchLibraryMode","Ordner");Check(v.Groups.SortedColumn.Name=="Anzahl"&&v.Groups.SortOrder==SortOrder.Ascending,"Ordnersortierung unabhängig erhalten");Call(c,"SwitchLibraryMode","Titel");v.Groups.Sort(v.Groups.Columns["Name"],ListSortDirection.Ascending);var reverse=All(v).OfType<Button>().Single(b=>b.Name=="Sortierrichtung");reverse.PerformClick();Check(v.Songs.SortedColumn.Name=="Titel"&&v.Songs.SortOrder==SortOrder.Ascending,"Richtungswechsel ignoriert Ereignis der unsichtbaren Liste");Call(v,"SortStudio","Interpret",false);Check(v.Songs.SortedColumn.Name=="Interpret","Sortiermenü verwendet aktive Liste");
 var row=v.Songs.Rows[0];v.Songs.ClearSelection();v.Songs.CurrentCell=row.Cells["Titel"];row.Selected=true;Call(c,"LoadPlayer",row.Tag);Call(c,"StartPlayer");device.Position=240000;device.Mode="stopped";var timer=(Timer)Field(c,"playerTimer");typeof(Timer).GetMethod("OnTick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(timer,new object[]{EventArgs.Empty});Check(device.OpenCount==2,"Ein Timer-Tick startet genau einen Folgetitel");Check(v.Songs.SelectedRows.Count==1&&Object.ReferenceEquals(v.Songs.SelectedRows[0].Tag,Field(c,"playerSong")),"Folgetitel ist markiert");timer.Stop();
 var playlist=new List<Song>{project.Folders[2].Songs[2],project.Folders[0].Songs[3]};typeof(Controller).GetField("playlistOrder",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(c,playlist);Call(c,"LoadPlayer",playlist[0]);Call(c,"PlayFollowingSong");Check(Object.ReferenceEquals(Field(c,"playerSong"),playlist[1]),"Automatische Weiterschaltung folgt Wiedergabeliste");timer.Stop();
 foreach(var page in new[]{"MP3Gain","fre:ac","FFmpeg","Konvertierung","Video-Audio-Import","Coversuche","Coverbearbeitung","Covergestaltung","Cover zuweisen / exportieren"}){Call(c,"OpenStudioModule",page);Pump();var host=v.ModuleHost;var list=(Control)Field(v,"studioLibrary");Check(list.Top==host.Bottom+2,"Liste unmittelbar unter Werkzeugen: "+page);Check(All(v).OfType<Button>().Count(b=>b.Visible&&(b.AccessibleName=="Titel anzeigen"||b.AccessibleName=="Ordner anzeigen"))==2,"Titel/Ordner in "+page);if(page=="fre:ac"||page=="FFmpeg"){var dest=All(host).OfType<TextBox>().Single(t=>t.ReadOnly&&!t.Multiline);var choose=All(host).OfType<Button>().Single(b=>b.Text=="Speicherort wählen");Check(dest.Parent==choose.Parent&&dest.Parent.Controls.GetChildIndex(dest)<dest.Parent.Controls.GetChildIndex(choose),"Zielpfad vor Auswahlbutton: "+page);}Check(!All(host).Any(x=>x is StudioTextSurface&&x.Dock==DockStyle.Fill),"Keine leere Fill-Protokollfläche: "+page);}
 v.SearchBox.Text="acdc song 7";Wait(()=>v.Songs.Rows.Count==3);All(v).OfType<Button>().Single(b=>b.AccessibleName=="Mikrofon ausschalten · Suchtext behalten").PerformClick();Check(v.SearchBox.Text=="acdc song 7","X bewahrt Suchtext");
 ((ProjectHistory)Field(c,"history")).MarkSaved();typeof(Controller).GetField("dirty",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(c,false);v.Close();}
 Console.WriteLine("BESTANDEN: "+count+" Windows-QS-Prüfungen. Audiogerät simuliert; kein physisches Mikrofon, keine visuelle Flackerabnahme.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{try{Directory.Delete(root,true);}catch{}}}
}
